export const GLOSSARY_SHARD = Object.freeze({"tokenomics":{"slug":"tokenomics","cat":"basics","en":"Tokenomics","contentLocale":"id","term":"Tokenomics","aka":["ekonomi token"],"short":"Tokenomics adalah desain ekonomi sebuah token, mencakup jumlah suplai, cara distribusi, jadwal unlock, kegunaan token, dan mekanisme yang menambah atau mengurangi suplai.","body":[["Bagian utama tokenomics meliputi max supply dan ",["circulating supply","circulating-supply"],", alokasi untuk tim, investor, komunitas, dan treasury, jadwal vesting, serta inflasi dari hadiah ",["staking","staking"],". Ada juga mekanisme deflasi seperti ",["token burn","token-burn"]," atau pembelian kembali."],["Kegunaan token sama pentingnya. Token bisa dipakai untuk membayar biaya, staking, voting governance, diskon ",["biaya trading","maker-taker-fees"],", atau tidak punya fungsi jelas sama sekali. Token dengan permintaan nyata dari penggunaan lebih mampu menyerap suplai baru."],["Untuk membaca tokenomics, cari dokumen resmi seperti whitepaper atau dokumentasi proyek, lalu bandingkan dengan ",["data on-chain","on-chain-analysis"]," dan situs pelacak unlock. Perhatikan apakah tim dan investor awal mendapat porsi besar dengan unlock yang cepat."]],"example":["Misalkan sebuah token punya suplai maksimal 1 miliar dengan alokasi: komunitas 40%, tim 20%, investor 20%, treasury 15%, dan ",["likuiditas","liquidity"]," 5%. Saat peluncuran hanya 10% yang beredar. Tim dan investor memiliki cliff 12 bulan lalu unlock bulanan selama 24 bulan. Setelah cliff, setiap bulan ada sekitar 400 juta / 24 = 16,7 juta token baru dari kedua kelompok itu, tekanan suplai yang perlu diperhitungkan."],"mistakes":["Hanya melihat harga dan market cap tanpa membaca jadwal alokasi dan unlock.","Percaya klaim deflasi tanpa memeriksa apakah burn benar-benar terjadi on-chain.","Mengabaikan inflasi dari hadiah staking yang terus menambah suplai."],"faq":[{"q":"Seperti apa tokenomics yang sehat?","a":"Umumnya distribusinya tidak terlalu terpusat, unlock tim dan investor bertahap, dan token punya kegunaan yang menciptakan permintaan nyata. Tetap tidak ada rumus yang menjamin harga."},{"q":"Di mana melihat tokenomics sebuah koin?","a":"Mulai dari dokumentasi resmi proyek, lalu cocokkan dengan block explorer, situs data pasar, dan pelacak jadwal unlock."}],"title":"Apa itu tokenomics? Arti ekonomi token kripto","description":"Pelajari arti tokenomics, cara membaca suplai, alokasi, vesting, dan kegunaan token sebelum Anda membeli sebuah aset kripto.","related":[["circulating-supply","Circulating supply (suplai beredar)","Circulating supply adalah jumlah koin atau token yang saat ini benar-benar beredar dan bisa diperdagangkan di pasar, tidak termasuk yang masih terkunci atau belum diterbitkan."],["token-unlock","Token unlock","Token unlock adalah saat sejumlah token yang sebelumnya terkunci, misalnya milik tim atau investor awal, dibuka sesuai jadwal vesting sehingga bisa dipindahkan atau dijual."],["fully-diluted-valuation","Fully diluted valuation (FDV)","Fully diluted valuation (FDV) adalah perkiraan nilai sebuah proyek kripto jika seluruh suplai maksimal tokennya sudah beredar, dihitung dari harga saat ini dikali suplai maksimal atau total."],["token-burn","Token burn","Token burn adalah penghapusan permanen sejumlah token dari peredaran dengan mengirimnya ke alamat yang tidak bisa diakses siapa pun, sehingga total suplai berkurang."],["governance-token","Governance token (token tata kelola)","Governance token adalah token yang memberi pemegangnya hak suara atas keputusan sebuah protokol atau DAO, seperti perubahan parameter, penggunaan kas, atau peningkatan kontrak."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"order-book":{"slug":"order-book","cat":"trading","en":"Order book","contentLocale":"id","term":"Order book (buku order)","aka":["buku order","orderbook","depth"],"short":"Order book adalah daftar real-time semua order beli dan order jual yang menunggu di sebuah pasangan perdagangan, disusun berdasarkan harga dan jumlahnya.","body":["Order book terdiri dari dua sisi. Sisi bid berisi order beli, dengan harga tertinggi di atas. Sisi ask berisi order jual, dengan harga terendah di atas. Selisih antara bid tertinggi dan ask terendah disebut spread. Ketika harga beli dan jual bertemu, mesin pencocokan exchange mengeksekusi transaksi.",["Order book menunjukkan ",["likuiditas","liquidity"]," atau kedalaman pasar. Jika di setiap level harga ada banyak koin, order besar bisa dieksekusi tanpa menggeser harga terlalu jauh. Jika order book tipis, ",["market order","market-order"]," besar akan memakan beberapa level harga dan menimbulkan ",["slippage","slippage"],"."],[["Limit order","limit-order"]," Anda masuk ke order book dan menunggu, sedangkan market order langsung mengambil order yang sudah ada. Perlu diingat, order besar yang terlihat di order book bisa ditarik kapan saja, jadi tidak selalu mencerminkan niat sebenarnya."]],"example":["Misalkan sisi ask sebuah pasangan berisi: 2 koin di 100,0 ",["USDT","usdt"],", 3 koin di 100,5 USDT, dan 5 koin di 101,0 USDT. Jika Anda membeli 6 koin dengan market order, Anda mendapat 2 koin di 100,0, 3 koin di 100,5, dan 1 koin di 101,0. Totalnya 200 + 301,5 + 101 = 602,5 USDT, sehingga harga rata-rata sekitar 100,42 USDT, lebih tinggi dari harga teratas 100,0."],"mistakes":["Memakai market order besar pada order book yang tipis.","Menganggap tembok order besar pasti menahan harga, padahal bisa dibatalkan kapan saja.","Bingung membedakan sisi bid dan ask saat memasang limit order."],"faq":[{"q":"Apa itu bid dan ask di order book?","a":"Bid adalah harga yang ditawarkan pembeli, ask adalah harga yang diminta penjual. Transaksi terjadi saat kedua sisi bertemu di harga yang sama."},{"q":"Bagaimana membaca kedalaman order book?","a":"Lihat berapa banyak koin yang tersedia di setiap level harga dekat harga saat ini. Makin besar jumlahnya, makin kecil dampak order Anda terhadap harga."}],"title":"Apa itu order book? Arti dan cara membacanya","description":"Arti order book di exchange kripto, cara membaca sisi bid dan ask, dan kenapa kedalaman pasar memengaruhi harga eksekusi Anda.","related":[["bid-ask-spread","Bid-ask spread (spread)","Bid-ask spread adalah selisih antara harga beli tertinggi (bid) dan harga jual terendah (ask) di order book pada satu waktu."],["limit-order","Limit order","Limit order adalah perintah membeli atau menjual di harga tertentu yang Anda tetapkan atau lebih baik, sehingga harga terkendali tetapi order belum tentu tereksekusi."],["market-order","Market order","Market order adalah perintah membeli atau menjual segera di harga terbaik yang tersedia saat itu, sehingga eksekusinya cepat tetapi harga akhirnya tidak dijamin."],["liquidity","Likuiditas (liquidity)","Likuiditas adalah seberapa mudah dan cepat sebuah aset kripto bisa dibeli atau dijual dalam jumlah besar tanpa menggeser harganya secara signifikan."],["slippage","Slippage","Slippage adalah selisih antara harga yang Anda harapkan saat mengirim order dan harga rata-rata yang benar-benar Anda dapatkan ketika order dieksekusi."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"Mengapa harga di layar bukan harga eksekusi saya?"},"coin":null,"tool":null,"cta":true},"liquidity":{"slug":"liquidity","cat":"trading","en":"Liquidity","contentLocale":"id","term":"Likuiditas (liquidity)","aka":["liquidity","likuid"],"short":"Likuiditas adalah seberapa mudah dan cepat sebuah aset kripto bisa dibeli atau dijual dalam jumlah besar tanpa menggeser harganya secara signifikan.","body":[["Pasar yang likuid punya banyak order beli dan jual di dekat ",["harga terakhir","last-price"],". Ciri-cirinya: spread antara harga bid dan ask tipis, ",["order book","order-book"]," tebal, dan ",["volume perdagangan","trading-volume"]," tinggi. Pasangan seperti ",["BTC","bitcoin"],"/",["USDT","usdt"]," di exchange besar biasanya sangat likuid, sedangkan token kecil yang baru listing sering tipis."],["Likuiditas penting karena menentukan harga eksekusi Anda. Di pasar tipis, ",["market order","market-order"]," besar akan \"memakan\" beberapa level harga sekaligus sehingga terjadi slippage. Likuiditas juga bisa berubah cepat: saat berita besar atau akhir pekan, market maker bisa menarik order dan pasar mendadak tipis."],"Di DeFi, likuiditas disediakan oleh liquidity pool, bukan order book. Prinsipnya sama: semakin besar dana di pool, semakin kecil dampak harga dari satu transaksi."],"example":"Bayangkan dua token sama-sama dihargai 1 USDT. Di token A, ada order jual senilai 200.000 USDT dalam rentang 0,5% di atas harga. Di token B, hanya ada 5.000 USDT di rentang yang sama. Jika Anda membeli 10.000 USDT dengan market order, di token A harga rata-rata Anda kira-kira tetap di sekitar 1,00. Di token B, order Anda menghabiskan seluruh 5.000 USDT pertama lalu naik ke level berikutnya, sehingga harga rata-rata bisa menjadi 1,03 atau lebih, alias kehilangan sekitar 300 USDT karena slippage.","mistakes":["Hanya melihat harga tanpa memeriksa kedalaman order book sebelum membeli token kecil.","Memakai market order besar di pasar tipis sehingga harga eksekusi jauh dari harga yang terlihat.","Menganggap volume 24 jam yang tinggi selalu berarti likuid, padahal volume bisa digelembungkan lewat wash trading."],"faq":[{"q":"Bagaimana cara mengecek likuiditas sebuah koin?","a":"Lihat spread bid-ask, kedalaman order book di kisaran 1-2% dari harga, dan volume di beberapa exchange. Spread tipis dan order book tebal menandakan likuiditas yang baik."},{"q":"Apa risiko trading koin yang likuiditasnya rendah?","a":"Anda bisa terkena slippage besar saat masuk dan keluar, dan sulit menjual dengan cepat ketika harga bergerak cepat. Stop loss juga bisa tereksekusi jauh dari harga pemicunya."}],"title":"Apa itu likuiditas dalam kripto? Arti dan cara mengeceknya","description":"Pahami arti likuiditas di pasar kripto, hubungannya dengan spread dan slippage, serta cara mengecek apakah sebuah koin cukup likuid.","related":[["order-book","Order book (buku order)","Order book adalah daftar real-time semua order beli dan order jual yang menunggu di sebuah pasangan perdagangan, disusun berdasarkan harga dan jumlahnya."],["slippage","Slippage","Slippage adalah selisih antara harga yang Anda harapkan saat mengirim order dan harga rata-rata yang benar-benar Anda dapatkan ketika order dieksekusi."],["bid-ask-spread","Bid-ask spread (spread)","Bid-ask spread adalah selisih antara harga beli tertinggi (bid) dan harga jual terendah (ask) di order book pada satu waktu."],["liquidity-pool","Liquidity pool (kolam likuiditas)","Liquidity pool adalah kumpulan token yang dikunci dalam smart contract, biasanya berpasangan, untuk melayani swap di DEX atau pinjaman di protokol DeFi."],["market-maker","Market maker","Market maker adalah pihak yang terus-menerus memasang order beli dan jual di dekat harga pasar sehingga trader lain selalu punya lawan transaksi, dan ia mendapat keuntungan dari selisih spread."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"Mengapa harga di layar bukan harga eksekusi saya?"},"coin":null,"tool":null,"cta":false},"isolated-margin":{"slug":"isolated-margin","cat":"derivatives","en":"Isolated margin","contentLocale":"id","term":"Margin terisolasi (isolated margin)","aka":["isolated margin","margin isolasi","mode isolated"],"short":"Margin terisolasi adalah mode margin di mana setiap posisi punya jaminan sendiri yang terpisah, sehingga jika posisi itu dilikuidasi, kerugiannya hanya terbatas pada margin yang dialokasikan ke posisi tersebut.","body":[["Dalam mode isolated, Anda menentukan berapa margin untuk setiap posisi. Saldo lain di akun futures tidak ikut dipakai untuk menahan posisi itu. Ini memudahkan pengendalian risiko: Anda tahu persis berapa maksimal yang bisa hilang dari satu trade jika terjadi ",["likuidasi","liquidation"],"."],["Konsekuensinya, posisi isolated lebih cepat dilikuidasi dibanding ",["cross margin","cross-margin"]," dengan saldo besar, karena jaminannya hanya sebesar margin yang dialokasikan. Anda bisa menambah margin secara manual untuk menjauhkan ",["harga likuidasi","liquidation-price"],", tetapi itu sama dengan menaikkan risiko yang Anda pertaruhkan."],["Isolated cocok untuk trade spekulatif, ",["altcoin","altcoin"]," yang volatil, atau saat Anda memegang beberapa posisi yang tidak saling berhubungan. Cara beralih mode dan aturan saat posisi masih terbuka berbeda tiap exchange."]],"example":["Akun futures Anda berisi 3.000 ",["USDT","usdt"],". Anda membuka long altcoin senilai 2.000 USDT di isolated dengan ",["leverage","leverage"]," 5x, jadi margin posisi 400 USDT. Jika altcoin anjlok sekitar 19% dan posisi dilikuidasi, Anda kehilangan sekitar 400 USDT, sementara 2.600 USDT lainnya tetap aman. Di cross margin, posisi yang sama bisa bertahan lebih lama, tetapi kerugiannya bisa menggerus sebagian besar dari 3.000 USDT."],"mistakes":["Menambah margin ke posisi isolated berulang kali sehingga fungsi pembatas risikonya hilang.","Lupa memeriksa mode margin sebelum membuka posisi, karena exchange bisa menyimpan pilihan terakhir.","Mengira isolated margin mencegah kerugian, padahal ia hanya membatasi kerugian per posisi."],"faq":[{"q":"Mana yang lebih baik, isolated atau cross margin?","a":"Isolated lebih mudah untuk membatasi kerugian per posisi, sedangkan cross memakai seluruh saldo sebagai jaminan sehingga posisi lebih tahan, tetapi risikonya menyebar ke seluruh akun."},{"q":"Bisakah saya mengubah isolated ke cross saat posisi terbuka?","a":"Tergantung exchange. Sebagian mengizinkan, sebagian mengharuskan posisi ditutup lebih dulu. Cek aturan di platform Anda."}],"title":"Apa itu isolated margin? Arti margin terisolasi di futures","description":"Pelajari margin terisolasi di futures kripto: cara kerja, kelebihan membatasi kerugian per posisi, dan bedanya dengan cross margin.","related":[["cross-margin","Margin silang (cross margin)","Margin silang adalah mode margin di mana seluruh saldo yang tersedia di akun futures dipakai bersama sebagai jaminan untuk semua posisi terbuka, sehingga posisi lebih sulit dilikuidasi tetapi seluruh saldo ikut dipertaruhkan."],["portfolio-margin","Portfolio margin","Portfolio margin adalah mode margin yang menghitung kebutuhan jaminan berdasarkan risiko gabungan seluruh portofolio, sehingga posisi yang saling mengimbangi bisa membutuhkan margin jauh lebih kecil."],["liquidation-price","Harga likuidasi (liquidation price)","Harga likuidasi adalah perkiraan harga mark price di mana posisi leverage Anda akan ditutup paksa karena margin yang tersisa turun ke level maintenance margin."],["leverage","Leverage (daya ungkit)","Leverage adalah fitur yang memungkinkan Anda membuka posisi lebih besar dari modal yang disetor, misalnya 10x berarti margin 100 USDT mengendalikan posisi senilai 1.000 USDT."]],"lesson":{"id":"E21","slug":"isolated-margin","ep":21,"title":"Margin terisolasi: menaruh satu perdagangan di kotaknya sendiri"},"coin":null,"tool":null,"cta":false},"index-price":{"slug":"index-price","cat":"derivatives","en":"Index price","contentLocale":"id","term":"Harga indeks (index price)","aka":["index price","indeks harga spot"],"short":"Harga indeks adalah rata-rata tertimbang harga spot sebuah aset dari beberapa exchange besar, dipakai exchange sebagai acuan untuk mark price, funding rate, dan settlement kontrak futures.","body":[["Exchange futures tidak ingin harga acuannya bergantung pada satu pasar saja. Karena itu, mereka mengambil harga spot dari beberapa exchange, misalnya ",["BTC","bitcoin"],"/",["USDT","usdt"]," dan BTC/USD di beberapa platform, lalu menghitung rata-rata tertimbang. Exchange yang harganya menyimpang terlalu jauh atau sedang bermasalah biasanya dikeluarkan sementara dari perhitungan."],["Harga indeks dipakai untuk beberapa hal: menghitung ",["mark price","mark-price"],", menentukan ",["funding rate","funding-rate"]," dari selisih harga ",["perpetual","perpetual-futures"]," terhadap indeks, dan menentukan harga settlement pada ",["futures berjangka","delivery-futures"],". Daftar sumber dan bobotnya umumnya dipublikasikan di halaman spesifikasi kontrak."],"Di DeFi, peran serupa dijalankan oleh oracle yang mengirim harga dari luar ke blockchain. Jika sumber indeks atau oracle bermasalah, harga acuan bisa menyimpang, sehingga kualitas sumber data sangat penting."],"example":"Misalkan indeks ETH sebuah exchange memakai tiga sumber dengan bobot sama: exchange A di 3.010, B di 3.004, dan C di 2.996 USDT. Harga indeksnya (3.010 + 3.004 + 2.996) dibagi 3 = 3.003,33 USDT. Jika harga ETH perpetual di exchange itu 3.018, harganya sekitar 0,49% di atas indeks. Selisih premium seperti ini mendorong funding rate menjadi positif, sehingga long membayar short.","mistakes":["Mengira harga indeks sama dengan harga di satu exchange spot favorit Anda.","Mengabaikan selisih antara harga perpetual dan indeks saat menilai funding rate.","Tidak membaca daftar sumber indeks untuk pasangan altcoin yang hanya diperdagangkan di sedikit exchange."],"faq":[{"q":"Apa beda harga indeks dan mark price?","a":"Harga indeks adalah rata-rata harga spot dari beberapa exchange. Mark price dihitung dari harga indeks ditambah komponen basis, dan dipakai untuk PnL serta likuidasi."},{"q":"Di mana saya bisa melihat sumber harga indeks?","a":"Biasanya di halaman spesifikasi kontrak atau halaman informasi indeks di exchange, yang mencantumkan exchange sumber dan bobotnya."}],"title":"Apa itu harga indeks (index price) di futures kripto?","description":"Pelajari harga indeks di futures kripto: cara dihitung dari beberapa exchange spot, fungsinya untuk mark price, funding, dan settlement.","related":[["mark-price","Mark price (harga tanda)","Mark price adalah harga acuan yang dihitung exchange dari harga indeks beberapa exchange spot dan basis kontrak, dipakai untuk menghitung unrealized PnL dan memicu likuidasi pada kontrak futures."],["last-price","Harga terakhir (last traded price)","Harga terakhir adalah harga transaksi paling akhir yang benar-benar terjadi di order book sebuah exchange, dan biasanya inilah angka yang Anda lihat di grafik dan daftar pasar."],["funding-rate","Funding rate","Funding rate adalah pembayaran berkala antara trader posisi long dan short di kontrak perpetual yang menjaga harga kontrak tetap dekat dengan harga spot."],["oracle","Oracle blockchain","Oracle blockchain adalah layanan yang membawa data dari luar blockchain, seperti harga aset, ke dalam smart contract agar kontrak bisa mengambil keputusan berdasarkan data tersebut."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"Likuidasi: siapa yang menekan tombol tutup paksa?"},"coin":null,"tool":"/funding-rates","cta":false},"yield-farming":{"slug":"yield-farming","cat":"defi","en":"Yield farming","contentLocale":"id","term":"Yield farming","aka":["liquidity mining","farming","bertani imbal hasil"],"short":"Yield farming adalah strategi menempatkan aset kripto di berbagai protokol DeFi, seperti liquidity pool atau lending, untuk mendapatkan fee, bunga, dan token insentif.","body":[["Bentuk paling umum adalah menyetor token ke ",["liquidity pool","liquidity-pool"],", menerima LP token, lalu melakukan ",["staking","staking"]," LP token itu di program farming untuk mendapat token reward tambahan. Ada juga farmer yang meminjamkan aset di protokol lending, atau menggabungkan beberapa protokol sekaligus untuk menumpuk imbal hasil."],["Angka ",["APR","apr-vs-apy"]," atau APY yang tinggi biasanya sebagian besar berasal dari token insentif, bukan dari fee. Jika harga token reward turun, imbal hasil riil ikut turun. Banyak program farming juga menurunkan emisi seiring waktu, sehingga angka yang terlihat hari ini jarang bertahan lama."],["Risiko yang perlu dihitung meliputi ",["impermanent loss","impermanent-loss"],", bug ",["smart contract","smart-contract"],", ",["rug pull","rug-pull"]," pada proyek kecil, biaya gas untuk masuk, klaim, dan keluar, serta risiko lapisan tambahan setiap kali Anda menggabungkan beberapa protokol."]],"example":"Misalnya Anda menaruh 5.000 USDC di sebuah farm yang menampilkan APR 20%: 8% dari fee dan 12% dari token reward. Setelah setahun, fee yang diperoleh sekitar 400 USDC. Token reward senilai 600 USDC saat dibagikan, tetapi harga token itu turun 50% sebelum Anda menjualnya, sehingga hanya bernilai 300 USDC. Imbal hasil riil Anda menjadi 700 USDC atau 14%, belum dikurangi biaya gas dan kemungkinan impermanent loss.","mistakes":["Memilih farm hanya dari angka APR tertinggi tanpa melihat komposisinya.","Tidak menghitung biaya gas yang bisa menghapus imbal hasil pada modal kecil.","Menyimpan token reward terlalu lama tanpa rencana, padahal harganya bisa terus turun karena emisi baru."],"faq":[{"q":"Apa beda yield farming dan staking?","a":"Staking biasanya mengunci koin untuk membantu mengamankan jaringan proof of stake. Yield farming memakai berbagai protokol DeFi untuk mengumpulkan fee dan token insentif, dengan risiko yang lebih beragam."},{"q":"Mengapa APR farming cepat turun?","a":"Karena lebih banyak dana masuk ke pool sehingga reward dibagi ke lebih banyak orang, emisi token dikurangi, atau harga token reward turun."}],"title":"Apa itu yield farming? Arti dan risikonya di DeFi","description":"Pelajari arti yield farming, sumber imbal hasilnya, mengapa APR tinggi bisa menipu, dan risiko yang perlu Anda hitung.","related":[["liquidity-pool","Liquidity pool (kolam likuiditas)","Liquidity pool adalah kumpulan token yang dikunci dalam smart contract, biasanya berpasangan, untuk melayani swap di DEX atau pinjaman di protokol DeFi."],["apr-vs-apy","APR vs APY","APR adalah tingkat imbal hasil tahunan tanpa bunga berbunga, sedangkan APY sudah memperhitungkan efek bunga berbunga (compounding), sehingga APY selalu sama atau lebih tinggi dari APR dengan tingkat dasar yang sama."],["impermanent-loss","Impermanent loss (kerugian tidak permanen)","Impermanent loss adalah selisih nilai antara menyetor token ke liquidity pool dan sekadar menyimpannya di dompet, yang muncul ketika harga kedua token di pool bergerak berbeda."],["staking","Staking","Staking adalah mengunci koin di jaringan proof of stake untuk membantu memvalidasi transaksi dan mengamankan jaringan, dengan imbalan berupa reward dalam koin yang sama."]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"mev":{"slug":"mev","cat":"defi","en":"MEV (maximal extractable value)","contentLocale":"id","term":"MEV (maximal extractable value)","aka":["maximal extractable value","miner extractable value","sandwich attack","front-running"],"short":"MEV adalah keuntungan tambahan yang bisa diambil oleh pihak yang mengatur urutan transaksi dalam sebuah blok, misalnya dengan mendahului atau mengapit transaksi pengguna lain.","body":[["Transaksi yang menunggu di ",["mempool","mempool"]," bisa dilihat publik. Bot pencari MEV (searcher) memindai transaksi tersebut dan mencari peluang, lalu membayar builder atau ",["validator","validator"]," agar transaksinya ditempatkan di urutan tertentu. Istilah ini dulu disebut miner extractable value sebelum ",["Ethereum","ethereum"]," beralih ke ",["proof of stake","proof-of-stake"],"."],["Sebagian MEV netral atau bahkan membantu pasar, seperti ",["arbitrase","arbitrage"]," yang menyamakan harga antar ",["DEX","dex"]," dan likuidasi posisi pinjaman. Bagian yang merugikan pengguna adalah sandwich attack: bot membeli tepat sebelum swap Anda sehingga harga naik, lalu menjual tepat setelahnya, dan Anda menerima harga yang lebih buruk dalam batas toleransi slippage Anda."],"Cara mengurangi dampaknya: atur toleransi slippage seketat yang masih masuk akal, hindari swap besar di pool tipis, pecah transaksi besar, atau gunakan RPC yang melindungi dari MEV dan agregator yang mengirim transaksi lewat jalur privat."],"example":"Anda menukar 20.000 USDC ke ETH saat harga 2.500 USDC, perkiraan hasil 8 ETH, dengan toleransi slippage 2% sehingga minimum diterima 7,84 ETH. Bot melihat transaksi Anda, membeli ETH lebih dulu sehingga harga naik, dan swap Anda hanya menghasilkan 7,85 ETH, masih di atas batas minimum sehingga tidak gagal. Bot lalu menjual ETH-nya. Anda kehilangan sekitar 0,15 ETH, setara 375 USDC, dibanding perkiraan awal.","mistakes":["Mengatur toleransi slippage sangat tinggi supaya swap tidak gagal.","Melakukan swap besar sekaligus di pool dengan likuiditas kecil.","Mengira MEV hanya terjadi di Ethereum, padahal juga muncul di banyak jaringan lain."],"faq":[{"q":"Apa itu sandwich attack?","a":"Serangan MEV di mana bot membeli tepat sebelum transaksi Anda dan menjual tepat sesudahnya, sehingga Anda mendapat harga lebih buruk dan bot mengambil selisihnya."},{"q":"Apakah MEV terjadi di exchange terpusat?","a":"MEV adalah fenomena on-chain yang terkait urutan transaksi di blok. Di exchange terpusat urutan order diatur oleh mesin pencocokan exchange, sehingga mekanismenya berbeda."}],"title":"Apa itu MEV? Arti maximal extractable value","description":"Pelajari arti MEV, cara kerja sandwich attack, dan langkah praktis untuk mengurangi kerugian saat swap di DEX.","related":[["mempool","Mempool","Mempool adalah ruang tunggu tempat transaksi yang sudah disiarkan tetapi belum masuk blok disimpan sementara oleh node, sebelum dipilih oleh penambang atau validator."],["slippage","Slippage","Slippage adalah selisih antara harga yang Anda harapkan saat mengirim order dan harga rata-rata yang benar-benar Anda dapatkan ketika order dieksekusi."],["dex","DEX (decentralized exchange)","DEX adalah exchange kripto yang berjalan di smart contract, di mana Anda bertransaksi langsung dari dompet sendiri tanpa menyetor dana ke perusahaan perantara."],["gas-fee","Gas fee (biaya gas)","Gas fee atau biaya gas adalah biaya yang Anda bayar kepada jaringan blockchain untuk memproses transaksi atau menjalankan smart contract, biasanya dalam coin asli jaringan tersebut."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"nft":{"slug":"nft","cat":"defi","en":"NFT (non-fungible token)","contentLocale":"id","term":"NFT (non-fungible token)","aka":["non-fungible token","token tidak dapat dipertukarkan","NFT"],"short":"NFT adalah token unik di blockchain yang mewakili kepemilikan atas satu item digital tertentu, seperti karya seni, koleksi, tiket, atau item game, sehingga tidak bisa ditukar satu banding satu dengan token lain.","body":[["Satu ",["BTC","bitcoin"]," atau satu ",["USDT","usdt"]," selalu sama dengan BTC atau USDT lain, sifat ini disebut fungible. NFT berbeda: setiap token punya ID sendiri dan metadata yang menunjuk ke gambar, audio, atau data lain. Standar paling umum di ",["Ethereum","ethereum"]," adalah ERC-721 dan ERC-1155, dan NFT juga ada di Solana, Bitcoin (Ordinals), serta jaringan lain."],["NFT dibuat (minting) melalui ",["smart contract","smart-contract"],", lalu diperdagangkan di marketplace. Pembuat bisa menetapkan royalti, tetapi penegakannya bergantung pada marketplace. Yang Anda miliki adalah token di ",["blockchain","blockchain"],". Hak cipta atas karya dan tempat file disimpan diatur terpisah, dan file yang disimpan di server terpusat bisa hilang jika server dimatikan."],["Risiko praktis yang sering terjadi bukan soal harga, melainkan keamanan. Situs mint palsu, ",["airdrop","airdrop"]," NFT spam yang mengarah ke situs penguras dompet, dan approval setApprovalForAll yang memberi izin memindahkan seluruh koleksi Anda adalah jebakan yang umum."]],"example":"Misalnya Anda mint sebuah NFT seharga 0,05 ETH ditambah biaya gas 0,004 ETH, total 0,054 ETH. Beberapa bulan kemudian Anda menjualnya di marketplace seharga 0,08 ETH. Marketplace memotong fee contoh 2,5% atau 0,002 ETH dan royalti pembuat contoh 5% atau 0,004 ETH, sehingga Anda menerima 0,074 ETH. Selisih bersih Anda 0,02 ETH, belum termasuk gas untuk listing jika diperlukan.","mistakes":["Mengklik tautan dari NFT tak dikenal yang tiba-tiba muncul di dompet.","Menandatangani setApprovalForAll di situs yang belum diverifikasi.","Mengira membeli NFT otomatis memberi hak cipta atas karya tersebut."],"faq":[{"q":"Apakah NFT memberi hak cipta atas karya?","a":"Tidak otomatis. Hak yang Anda peroleh bergantung pada lisensi dari pembuat. Banyak NFT hanya memberi kepemilikan token, bukan hak cipta."},{"q":"Di mana file NFT disimpan?","a":"Biasanya bukan di blockchain itu sendiri, melainkan di penyimpanan seperti IPFS, Arweave, atau server biasa. Metadata NFT menunjuk ke lokasi tersebut."}],"title":"Apa itu NFT? Arti non-fungible token di kripto","description":"Pelajari arti NFT, cara kerja minting dan marketplace, apa yang sebenarnya Anda miliki, serta jebakan keamanan yang umum.","related":[["smart-contract","Smart contract","Smart contract adalah program yang disimpan dan dijalankan di blockchain, yang otomatis mengeksekusi aturan tertentu ketika syaratnya terpenuhi, tanpa perlu perantara."],["token-approval","Token approval (izin token)","Token approval adalah izin yang Anda berikan dari dompet kepada smart contract agar kontrak tersebut boleh memindahkan token tertentu milik Anda hingga batas jumlah yang disetujui."],["phishing","Phishing (penipuan pancingan)","Phishing adalah penipuan yang meniru pihak tepercaya, seperti exchange, dompet, atau proyek kripto, untuk memancing Anda menyerahkan kata sandi, kode 2FA, seed phrase, atau menandatangani transaksi berbahaya."],["coin-vs-token","Coin vs token","Coin adalah aset asli sebuah blockchain yang dipakai untuk membayar biaya jaringan, sedangkan token adalah aset yang dibuat di atas blockchain lain melalui smart contract."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"vasp":{"slug":"vasp","cat":"regulation","en":"VASP (virtual asset service provider)","contentLocale":"id","term":"VASP (penyedia jasa aset virtual)","aka":["Virtual Asset Service Provider","PJAK","CASP"],"short":"VASP adalah istilah FATF untuk perusahaan yang menyediakan jasa aset kripto bagi orang lain, seperti bursa, penyedia kustodi, dan layanan transfer, yang wajib mematuhi aturan AML dan KYC.","body":[["FATF memakai istilah Virtual Asset Service Provider untuk bisnis yang menukar, mentransfer, menyimpan, atau mengelola ",["aset kripto","cryptocurrency"]," atas nama orang lain. ",["Dompet non-kustodian","non-custodial-wallet"]," yang Anda kendalikan sendiri dengan ",["seed phrase","seed-phrase"]," biasanya tidak termasuk VASP."],["Tiap negara punya nama dan izin sendiri. Uni Eropa memakai istilah CASP dalam ",["MiCA","mica"],". Di Indonesia, bursa yang melayani masyarakat dikenal sebagai Pedagang Aset Keuangan Digital atau pedagang aset kripto, yang kini diawasi OJK. Status izin di satu negara tidak otomatis berlaku di negara lain."],"Bagi pengguna, status VASP berizin berarti ada aturan perlindungan konsumen, pemisahan dana nasabah, dan jalur pengaduan. Namun izin bukan jaminan bebas risiko. Cek daftar resmi regulator, bukan klaim di iklan atau media sosial."],"example":"Misalkan Anda membandingkan dua platform. Platform A tercantum dalam daftar pedagang aset kripto berizin di situs regulator, sedangkan platform B hanya menulis memiliki lisensi internasional tanpa nomor izin yang bisa dicek. Anda berencana menyimpan 10 juta rupiah. Di platform A, jika ada sengketa, Anda punya jalur pengaduan resmi. Di platform B, Anda tidak tahu regulator mana yang bisa dihubungi. Perbedaan ini tidak terlihat di tampilan aplikasi, tetapi sangat penting saat terjadi masalah.","mistakes":["Percaya klaim lisensi tanpa mengeceknya langsung di daftar resmi regulator.","Mengira izin di satu negara berlaku untuk pengguna di semua negara.","Menganggap dompet non-kustodian juga diawasi seperti bursa."],"faq":[{"q":"Apa beda VASP dan CASP?","a":"VASP adalah istilah global dari FATF, sedangkan CASP adalah istilah yang dipakai Uni Eropa dalam MiCA. Keduanya merujuk pada penyedia jasa aset kripto, dengan persyaratan izin yang ditentukan aturan masing-masing."},{"q":"Bagaimana cara mengecek bursa berizin di Indonesia?","a":"Cek daftar pedagang aset kripto berizin di situs resmi regulator, yaitu OJK sejak pengawasan dialihkan dari Bappebti pada Januari 2025. Cocokkan nama badan hukum, bukan hanya nama merek aplikasi."}],"title":"Apa itu VASP? Arti penyedia jasa aset kripto","description":"Pelajari arti VASP menurut FATF, bedanya dengan CASP di MiCA, dan cara mengecek apakah bursa kripto benar berizin.","related":[["kyc","KYC (Know Your Customer)","KYC adalah proses verifikasi identitas yang wajib dilakukan bursa kripto dan lembaga keuangan, misalnya dengan KTP, foto wajah, dan data alamat, sebelum Anda bisa memakai layanan penuh."],["mica","MiCA (regulasi aset kripto Uni Eropa)","MiCA adalah regulasi Uni Eropa tentang pasar aset kripto yang mengatur penerbit stablecoin dan penyedia jasa aset kripto (CASP) dengan satu set aturan untuk semua negara anggota."],["travel-rule","Travel rule","Travel rule adalah aturan yang mewajibkan penyedia jasa aset kripto mengirim dan menerima data pengirim serta penerima bersama transfer kripto, mengikuti Rekomendasi 16 FATF."],["centralized-exchange","Centralized exchange (CEX)","Centralized exchange (CEX) adalah platform jual beli kripto yang dijalankan oleh sebuah perusahaan, yang menyimpan dana pengguna, mencocokkan order, dan biasanya mewajibkan verifikasi KYC."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"Temukan pintu yang asli: Jangan buka akun sembarangan"},"coin":null,"tool":"/topics/compliant-exchanges","cta":false},"mica":{"slug":"mica","cat":"regulation","en":"MiCA (EU Markets in Crypto-Assets)","contentLocale":"id","term":"MiCA (regulasi aset kripto Uni Eropa)","aka":["Markets in Crypto-Assets","regulasi MiCA"],"short":"MiCA adalah regulasi Uni Eropa tentang pasar aset kripto yang mengatur penerbit stablecoin dan penyedia jasa aset kripto (CASP) dengan satu set aturan untuk semua negara anggota.","body":[["Sebelum MiCA, tiap negara Uni Eropa punya aturan kripto sendiri. MiCA menyatukannya. Aturan ",["stablecoin","stablecoin"],", yang disebut e-money token dan asset-referenced token, berlaku sejak 30 Juni 2024. Aturan untuk ",["CASP","vasp"]," berlaku sejak 30 Desember 2024, dengan masa transisi nasional paling lambat sampai 1 Juli 2026."],"CASP yang punya izin MiCA di satu negara anggota bisa melayani pengguna di seluruh Uni Eropa lewat sistem passporting. Penerbit stablecoin wajib memenuhi syarat cadangan, transparansi, dan hak penebusan. Akibatnya, beberapa bursa membatasi stablecoin yang belum memenuhi MiCA untuk pengguna di Eropa.","Bagi pengguna di Indonesia, MiCA tidak berlaku langsung. Namun MiCA memengaruhi pasar global: stablecoin mana yang tersedia, cara bursa menyusun produk, dan standar keterbukaan informasi yang sering menjadi rujukan negara lain."],"example":["Misalkan Anda tinggal di Jerman dan memegang 2.000 ",["USDT","usdt"]," di bursa global. Setelah aturan stablecoin MiCA berlaku, bursa tersebut membatasi ",["pasangan perdagangan","trading-pair"]," USDT untuk pengguna Uni Eropa dan menyarankan ",["konversi","instant-convert"]," ke stablecoin yang memenuhi MiCA, seperti ",["USDC","usdc"],". Jika selisih kurs konversi 0,1%, Anda kehilangan sekitar 2 USDT dan menerima kira-kira 1.998 USDC. Pengguna dengan akun yang sama di Indonesia mungkin tidak mengalami pembatasan ini, karena aturannya berbeda per wilayah."],"mistakes":["Mengira MiCA berlaku langsung untuk pengguna di luar Uni Eropa.","Menganggap izin MiCA berarti bursa bebas risiko.","Lupa bahwa ketersediaan stablecoin di bursa bisa berbeda tergantung wilayah akun."],"faq":[{"q":"Kapan MiCA mulai berlaku?","a":"Aturan stablecoin berlaku sejak 30 Juni 2024 dan aturan CASP sejak 30 Desember 2024. Negara anggota boleh memberi masa transisi paling lama sampai 1 Juli 2026."},{"q":"Apakah USDT dilarang oleh MiCA?","a":"MiCA tidak menyebut nama koin tertentu, tetapi mewajibkan penerbit stablecoin memenuhi syarat izin. Karena itu beberapa bursa membatasi perdagangan USDT untuk pengguna di Uni Eropa."}],"title":"Apa itu MiCA? Regulasi kripto Uni Eropa","description":"Pahami MiCA: aturan stablecoin dan CASP di Uni Eropa, tanggal berlakunya, dan dampaknya bagi pasar kripto global.","related":[["vasp","VASP (penyedia jasa aset virtual)","VASP adalah istilah FATF untuk perusahaan yang menyediakan jasa aset kripto bagi orang lain, seperti bursa, penyedia kustodi, dan layanan transfer, yang wajib mematuhi aturan AML dan KYC."],["stablecoin","Stablecoin","Stablecoin adalah aset kripto yang dirancang menjaga nilai stabil terhadap aset acuan, biasanya 1 dolar AS, seperti USDT dan USDC, sehingga dipakai sebagai alat tukar dan tempat parkir dana di pasar kripto."],["usdc","USDC (USD Coin)","USDC adalah stablecoin yang diterbitkan Circle dan dirancang bernilai 1 dolar AS, didukung cadangan kas dan surat utang pemerintah AS jangka pendek, serta banyak dipakai di DeFi dan exchange."],["kyc","KYC (Know Your Customer)","KYC adalah proses verifikasi identitas yang wajib dilakukan bursa kripto dan lembaga keuangan, misalnya dengan KTP, foto wajah, dan data alamat, sebelum Anda bisa memakai layanan penuh."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"Temukan pintu yang asli: Jangan buka akun sembarangan"},"coin":null,"tool":null,"cta":false},"dual-investment":{"slug":"dual-investment","cat":"exchange-features","en":"Dual investment","contentLocale":"id","term":"Dual investment (investasi ganda)","aka":["dual investment","Dual Asset","investasi ganda"],"short":"Dual investment adalah produk terstruktur bursa yang memberi imbal hasil tinggi, tetapi saat jatuh tempo Anda bisa menerima aset yang berbeda dari yang disetor, tergantung harga terhadap target.","body":[["Ada dua arah. Buy Low: Anda menyetor ",["USDT","usdt"],", dan jika harga saat jatuh tempo di bawah harga target, USDT Anda dikonversi menjadi koin di harga target. Sell High: Anda menyetor koin, dan jika harga di atas target, koin Anda dijual di harga target dan Anda menerima USDT. Dalam kedua kasus Anda tetap mendapat imbal hasil."],["Di balik layar, produk ini mirip menjual opsi. Imbal hasil tinggi adalah premi atas kesediaan Anda membeli atau menjual di harga tertentu. Semakin dekat harga target dengan ",["harga pasar","last-price"]," dan semakin tinggi ",["volatilitas","volatility"],", semakin tinggi imbal hasilnya, dan semakin besar kemungkinan ",["konversi","instant-convert"],"."],"Risikonya: Anda bisa membeli koin di harga yang ternyata jauh di atas harga pasar saat jatuh tempo, atau kehilangan kenaikan besar karena koin sudah terjual. Dana juga biasanya terkunci sampai jatuh tempo."],"example":["Misalkan ",["BTC","bitcoin"]," di 62.000 USDT dan Anda memilih Buy Low dengan target 60.000, tenor 7 hari, ",["APR","apr-vs-apy"]," 40%, modal 6.000 USDT. Imbal hasilnya sekitar 6.000 kali 40% kali 7/365, yaitu 46 USDT. Jika saat jatuh tempo BTC di 63.000, Anda menerima 6.046 USDT. Jika BTC turun ke 55.000, modal dan imbal hasil dikonversi di harga 60.000, sehingga Anda menerima sekitar 0,1008 BTC. Nilainya di harga pasar hanya sekitar 5.543 USDT, jadi Anda rugi sekitar 457 USDT meski mendapat imbal hasil."],"mistakes":["Tergiur APR tinggi tanpa memahami bahwa aset bisa dikonversi.","Memilih harga target yang tidak benar-benar Anda inginkan sebagai harga beli atau jual.","Mengira dual investment dijamin modal seperti simpanan biasa."],"faq":[{"q":"Apakah dual investment bisa rugi?","a":"Bisa, dalam arti nilai yang Anda terima lebih rendah daripada jika Anda tidak ikut. Jumlah unitnya tidak berkurang, tetapi aset bisa dikonversi di harga yang kurang menguntungkan dibanding harga pasar."},{"q":"Kenapa APR dual investment sangat tinggi?","a":"Karena imbal hasilnya berasal dari premi opsi. Premi tinggi berarti peluang konversi juga tinggi, terutama saat pasar sangat volatil."}],"title":"Apa itu dual investment? Cara kerja dan risikonya","description":"Pahami dual investment: Buy Low dan Sell High, cara menghitung imbal hasil, dan kapan aset Anda dikonversi.","related":[["options","Opsi kripto (crypto options)","Opsi kripto adalah kontrak yang memberi pembelinya hak, tetapi bukan kewajiban, untuk membeli (call) atau menjual (put) aset kripto pada harga tertentu (strike) sampai atau pada tanggal jatuh tempo, dengan membayar premi."],["crypto-earn","Crypto Earn (produk simpanan kripto)","Crypto Earn adalah kategori produk di bursa yang memberi imbal hasil atas aset kripto yang Anda simpan, misalnya simpanan fleksibel, simpanan berjangka, staking, atau produk terstruktur."],["apr-vs-apy","APR vs APY","APR adalah tingkat imbal hasil tahunan tanpa bunga berbunga, sedangkan APY sudah memperhitungkan efek bunga berbunga (compounding), sehingga APY selalu sama atau lebih tinggi dari APR dengan tingkat dasar yang sama."],["volatility","Volatility (volatilitas)","Volatilitas adalah ukuran seberapa besar dan seberapa cepat harga sebuah aset bergerak naik turun dalam periode tertentu."]],"lesson":null,"coin":null,"tool":null,"cta":false},"unified-trading-account":{"slug":"unified-trading-account","cat":"exchange-features","en":"Unified trading account (UTA)","contentLocale":"id","term":"Akun trading terpadu (Unified Trading Account)","aka":["Unified Trading Account","UTA","akun terpadu","unified account"],"short":"Akun trading terpadu adalah jenis akun bursa yang menggabungkan saldo spot, margin, futures, dan opsi dalam satu dompet, sehingga satu pool aset bisa dipakai sebagai margin untuk berbagai produk.","body":[["Di akun klasik, Anda harus memindahkan dana antara dompet spot dan futures sebelum membuka posisi. Di akun terpadu, saldo seperti ",["USDT","usdt"],", ",["BTC","bitcoin"],", atau ",["ETH","ethereum"]," langsung bisa dipakai sebagai jaminan. Bybit, OKX, dan Bitget punya versi masing-masing dengan nama dan mode yang sedikit berbeda."],["Aset non-",["stablecoin","stablecoin"]," biasanya dihitung dengan potongan nilai jaminan (haircut). Misalnya BTC senilai 1.000 USDT mungkin hanya dihitung 950 USDT sebagai margin. Profit dan rugi dari posisi berbeda juga bisa saling mengimbangi, terutama di ",["mode cross","cross-margin"]," margin atau ",["portfolio margin","portfolio-margin"],"."],"Kelebihannya efisiensi modal dan lebih sedikit transfer. Kekurangannya, risiko menjadi saling terhubung: kerugian di satu posisi bisa memakai jaminan yang Anda anggap tabungan spot. Pahami mode margin akun Anda sebelum memakai leverage."],"example":"Misalkan akun terpadu Anda berisi 0,05 BTC di harga 60.000 USDT, senilai 3.000 USDT, dan 1.000 USDT. Dengan haircut BTC 5%, nilai jaminan BTC dihitung 2.850, total jaminan 3.850 USDT. Anda membuka long ETH perpetual dengan margin terpakai 1.500 USDT. Jika ETH turun tajam dan kerugian posisi mencapai 1.200 USDT, kerugian itu mengurangi jaminan gabungan, termasuk nilai BTC Anda. Jika BTC ikut turun 10%, nilai jaminannya berkurang sekitar 285 USDT lagi, sehingga risiko likuidasi meningkat dari dua arah.","mistakes":["Menyimpan tabungan jangka panjang di akun terpadu yang juga dipakai untuk trading leverage.","Tidak memahami haircut sehingga mengira nilai jaminan sama dengan nilai pasar aset.","Memakai mode cross margin tanpa sadar bahwa semua saldo bisa ikut menanggung kerugian."],"faq":[{"q":"Apa keuntungan akun trading terpadu?","a":"Anda tidak perlu memindahkan dana antarproduk, dan modal bisa dipakai lebih efisien. Profit dari satu posisi juga bisa menopang posisi lain."},{"q":"Apakah akun terpadu lebih berisiko?","a":"Bisa, karena semua aset dan posisi saling terhubung sebagai jaminan. Kerugian besar di satu posisi dapat memicu likuidasi yang memengaruhi saldo lain."}],"title":"Apa itu Unified Trading Account? Akun trading terpadu","description":"Pelajari cara kerja akun trading terpadu atau UTA, haircut jaminan, mode margin, dan risiko yang saling terhubung.","related":[["cross-margin","Margin silang (cross margin)","Margin silang adalah mode margin di mana seluruh saldo yang tersedia di akun futures dipakai bersama sebagai jaminan untuk semua posisi terbuka, sehingga posisi lebih sulit dilikuidasi tetapi seluruh saldo ikut dipertaruhkan."],["portfolio-margin","Portfolio margin","Portfolio margin adalah mode margin yang menghitung kebutuhan jaminan berdasarkan risiko gabungan seluruh portofolio, sehingga posisi yang saling mengimbangi bisa membutuhkan margin jauh lebih kecil."],["sub-account","Sub-akun (sub-account)","Sub-akun adalah akun tambahan di bawah akun utama bursa yang punya saldo, posisi, dan API key terpisah, sehingga Anda bisa memisahkan strategi atau dana tanpa membuat akun baru dengan KYC lain."],["margin-trading","Margin trading","Margin trading adalah cara trading dengan meminjam dana dari exchange menggunakan aset Anda sebagai jaminan, sehingga Anda bisa membuka posisi lebih besar dari saldo sendiri atau menjual aset yang dipinjam."]],"lesson":null,"coin":null,"tool":null,"cta":true},"withdrawal-fee":{"slug":"withdrawal-fee","cat":"exchange-features","en":"Withdrawal fee","contentLocale":"id","term":"Biaya penarikan (withdrawal fee)","aka":["withdrawal fee","biaya withdraw","biaya WD"],"short":"Biaya penarikan adalah biaya yang dipotong bursa saat Anda menarik kripto ke alamat lain atau menarik rupiah ke rekening bank, biasanya berupa jumlah tetap per transaksi yang bergantung pada koin dan jaringan.","body":[["Untuk kripto, biaya penarikan umumnya ditetapkan per koin dan per jaringan, bukan persentase. Bursa memakainya untuk menutup ",["biaya gas","gas-fee"]," jaringan, dan kadang menambah margin. Karena itu, menarik ",["USDT","usdt"]," lewat jaringan ",["Ethereum","ethereum"]," (ERC20) biasanya jauh lebih mahal daripada lewat TRON, Solana, atau jaringan ",["layer 2","layer-2"],"."],["Biaya ini berbeda dari ",["biaya trading","maker-taker-fees"],". Bursa yang murah untuk trading belum tentu murah untuk penarikan. Banyak bursa juga punya jumlah minimum penarikan. Biaya bisa berubah sewaktu-waktu mengikuti kondisi jaringan, jadi cek angka yang tampil di layar penarikan."],"Yang terpenting: pilih jaringan yang didukung oleh alamat tujuan. Biaya murah tidak berarti apa-apa jika Anda mengirim ke jaringan yang salah, karena dana bisa tidak sampai atau sulit dipulihkan."],"example":["Misalkan Anda ingin menarik 100 USDT. Di layar penarikan, jaringan ERC20 dikenai biaya 3 USDT, TRC20 1 USDT, dan sebuah jaringan layer 2 0,3 USDT. Jika memakai ERC20, Anda menerima 97 USDT, artinya biaya 3%. Lewat layer 2, Anda menerima 99,7 USDT, hanya 0,3%. Namun jika alamat tujuan Anda hanya mendukung TRC20, maka TRC20 adalah pilihan yang benar. Untuk jumlah 5.000 USDT, biaya tetap 3 USDT di ERC20 hanya 0,06%, sehingga ",["pilihan jaringan","blockchain-network"]," menjadi kurang berpengaruh."],"mistakes":["Memilih jaringan termurah tanpa memastikan alamat tujuan mendukung jaringan itu.","Menarik dalam jumlah kecil berkali-kali sehingga biaya tetap menumpuk.","Membandingkan bursa hanya dari biaya trading dan melupakan biaya penarikan."],"faq":[{"q":"Kenapa biaya penarikan USDT berbeda-beda?","a":"Karena setiap jaringan punya biaya gas berbeda. Bursa menetapkan biaya per jaringan, jadi USDT di Ethereum biasanya lebih mahal daripada di TRON atau jaringan layer 2."},{"q":"Apakah biaya penarikan bisa dihindari?","a":"Transfer internal antar pengguna di bursa yang sama sering gratis. Untuk penarikan on-chain, Anda bisa memilih jaringan yang lebih murah asalkan didukung alamat tujuan."}],"title":"Apa itu biaya penarikan kripto? Cara memilih jaringan","description":"Pahami biaya penarikan di bursa kripto, kenapa biaya berbeda per jaringan, dan cara menghitung biaya sebelum withdraw.","related":[["gas-fee","Gas fee (biaya gas)","Gas fee atau biaya gas adalah biaya yang Anda bayar kepada jaringan blockchain untuk memproses transaksi atau menjalankan smart contract, biasanya dalam coin asli jaringan tersebut."],["blockchain-network","Jaringan deposit (pilihan chain)","Jaringan deposit adalah blockchain yang Anda pilih untuk mengirim atau menerima sebuah aset, misalnya USDT lewat Tron, Ethereum, atau BNB Smart Chain, dan pilihan ini harus sama di sisi pengirim dan penerima."],["maker-taker-fees","Biaya maker dan taker (maker-taker fee)","Biaya maker dan taker adalah dua tarif biaya trading di exchange: maker dikenakan pada order yang menambah likuiditas ke order book, sedangkan taker dikenakan pada order yang langsung mengambil likuiditas yang sudah ada."],["layer-2","Layer 2 (L2)","Layer 2 (L2) adalah jaringan yang dibangun di atas blockchain layer 1, memproses transaksi di luar jaringan utama lalu menyetor ringkasannya ke L1 agar lebih cepat dan murah."]],"lesson":{"id":"E08","slug":"sell-vs-withdraw","ep":8,"title":"Saya sudah jual. Mengapa uangnya belum masuk ke rekening bank?"},"coin":null,"tool":"/rates","cta":false}});
